  function idbReset(v) { return idbTx('readwrite', function (st) { st.clear(); st.put(v, IDB_REC); }); }

  // Writes are debounced and serialised through one promise chain, so they can never interleave.
  var storageWarned = false, saveTimer = null, writeQ = Promise.resolve();
