  function saveUi() { lsSet(UIKEY, JSON.stringify(ui)); }
  var stP = uiState('p', { q: '', cat: '', loc: '', sort: 'name', dir: 1, low: false, page: 0 });
  var stM = uiState('m', { q: '', type: '', loc: '', from: '', to: '', page: 0 });
  var stPO = uiState('po', { q: '', status: '', sup: '', page: 0 });
  var stSO = uiState('so', { q: '', status: '', loc: '', page: 0 });
  var stC = uiState('c', { q: '', type: '', page: 0 });
  var stS = uiState('s', { q: '', page: 0 });
  var stI = uiState('inv', { q: '', status: '', age: '', page: 0 });

  // ── Formatting ───────────────────────────────────────────────────────────
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  var NF2 = new Intl.NumberFormat('sl-SI', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var NF0 = new Intl.NumberFormat('sl-SI', { maximumFractionDigits: 0 });
  function eur(n) { return NF2.format(n || 0) + ' €'; }
  function eur0(n) { return NF0.format(Math.round(n || 0)) + ' €'; }
  function num(n) { return NF0.format(n || 0); }
  function fdate(s) { return s ? s.slice(8, 10) + '.' + s.slice(5, 7) + '.' + s.slice(0, 4) : '—'; }
  function fts(ts) { return ts ? fdate(ts.slice(0, 10)) + ' ' + ts.slice(11, 16) : '—'; }
