    db.pos.forEach(function (p) { docs.push({ ts: p.created || p.date, html: '<a href="#/purchasing/' + p.id + '">' + esc(p.no) + '</a>', sub: 'Purchase order · ' + esc((IX.s[p.supplierId] || {}).name || ''), right: eur(poValue(p)), badge: poBadge(p) }); });
    db.invoices.forEach(function (i) { docs.push({ ts: i.created || (i.date + 'T12:00'), html: '<a href="#/invoices/' + i.id + '">Invoice ' + esc(i.no) + '</a>', sub: 'Invoice · ' + esc((IX.c[i.customerId] || {}).name || ''), right: eur(i.total), badge: invBadge(i) }); });
    docs.sort(function (a, b) { return a.ts < b.ts ? 1 : a.ts > b.ts ? -1 : 0; });
    var maxLoc = 0; LOCS.forEach(function (l) { maxLoc = Math.max(maxLoc, byLoc[l.id] || 0); });
