        var pos = db.pos.filter(function (p) { return p.supplierId === id; }).sort(function (a, b) { return a.date < b.date ? 1 : -1; });
        var spend = 0; pos.forEach(function (p) { if (p.status !== 'cancelled' && p.status !== 'draft' && p.date >= addDays(TODAY, -365)) spend += poValue(p); });
