          '<td class="num">' + eur(cn.total) + '</td><td class="num">' + eur(cn.applied || 0) + '</td><td class="num">' + eur(cn.refund ? cn.refund.amount : 0) + '</td><td>' + badge(s[0], s[1]) + '</td></tr>';
